                {"name": "Pizza & Code", "email": "pizzacode@tech.edu", "avatar": "https://images.unsplash.com/photo-1513104890138-7c749659a591?w=200&auto=format&fit=crop&q=60", "venue": "Pizza & Code", "description": "Pizza delivery for late night coding sessions.", "cover": "https://images.unsplash.com/photo-1574071318508-1cdbab80d002?w=800&auto=format&fit=crop&q=60", "category": "Food", "services": [{"name": "Pizza Delivery", "desc": "Fast delivery to dorms", "duration": 30, "price": 3}, {"name": "Hackathon Package", "desc": "Pizza for hackathons", "duration": 45, "price": 80}, {"name": "Bulk Order", "desc": "Large orders for events", "duration": 60, "price": 120}, {"name": "Pickup Order", "desc": "Order ahead", "duration": 15, "price": 0}]},
                {"name": "The Lab Cafe", "email": "labcafe@tech.edu", "avatar": "https://images.unsplash.com/photo-1509042239860-f550ce710b93?w=200&auto=format&fit=crop&q=60", "venue": "The Lab Cafe", "description": "Cafe in the CS building. Perfect for study groups.", "cover": "https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?w=800&auto=format&fit=crop&q=60", "category": "Food", "services": [{"name": "Study Group Package", "desc": "Coffee + snacks", "duration": 60, "price": 45}, {"name": "Table Reservation", "desc": "Reserve study space", "duration": 120, "price": 0}, {"name": "Event Catering", "desc": "Catering for CS events", "duration": 120, "price": 180}, {"name": "Private Room", "desc": "Reserve private room", "duration": 180, "price": 100}]},
                {"name": "Meal Prep Tech", "email": "mealpreptech@tech.edu", "avatar": "https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=200&auto=format&fit=crop&q=60", "venue": "Meal Prep Tech", "description": "Meal prep for busy CS students. Healthy and quick.", "cover": "https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop&q=60", "category": "Food", "services": [{"name": "Weekly Meal Prep", "desc": "5 meals for the week", "duration": 60, "price": 55}, {"name": "Bulk Order", "desc": "Meal prep for groups", "duration": 120, "price": 250}, {"name": "Custom Plan", "desc": "Personalized meal plan", "duration": 90, "price": 80}, {"name": "Nutrition Consult", "desc": "Nutrition consultation", "duration": 45, "price": 35}]},
                {"name": "The Debug Bar", "email": "debugbar@tech.edu", "avatar": "https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=200&auto=format&fit=crop&q=60", "venue": "The Debug Bar", "description": "Bar for CS students. 21+ only. Open late.", "cover": "https://images.unsplash.com/photo-1470337458703-46ad1756a187?w=800&auto=format&fit=crop&q=60", "category": "Food", "services": [{"name": "Table Reservation", "desc": "Reserve a table", "duration": 120, "price": 0}, {"name": "Private Event", "desc": "Reserve for events", "duration": 240, "price": 300}, {"name": "Bar Rental", "desc": "Full bar rental", "duration": 360, "price": 600}, {"name": "Catering", "desc": "Food and drinks", "duration": 180, "price": 250}]}
            ]
        }
    ]'::jsonb;

BEGIN
    -- Clean Slate: Delete all existing data
    DELETE FROM public.availability;
    DELETE FROM public.reviews;
    DELETE FROM public.bookings;
    DELETE FROM public.services;
    DELETE FROM public.venues;
    DELETE FROM public.users;
    DELETE FROM auth.users;

    -- Loop through each campus
    FOR campus_data IN SELECT value FROM jsonb_array_elements(providers_data)
    LOOP
        -- Loop through each provider in the campus
        FOR provider_json IN SELECT value FROM jsonb_array_elements(campus_data->'providers')
        LOOP
            -- Generate new IDs for user and venue
            new_user_id := uuid_generate_v4();
            new_venue_id := uuid_generate_v4();

            -- Insert into auth.users (Supabase auth table)
            INSERT INTO auth.users (id, email, raw_user_meta_data, created_at)
            VALUES (
                new_user_id,
                provider_json->>'email',
                json_build_object(
                    'full_name', provider_json->>'name',
                    'avatar_url', provider_json->>'avatar'
                ),
                NOW()
            );

            -- Insert venue with approved status for testing
            INSERT INTO public.venues (id, owner_id, name, description, campus, image_url, category, status)
            VALUES (
                new_venue_id,
                new_user_id,
                provider_json->>'venue',
                provider_json->>'description',
                campus_data->>'campus',
                provider_json->>'cover',
                provider_json->>'category',
                'approved'
            );

            -- Insert services for this venue
            FOR service_json IN SELECT value FROM jsonb_array_elements(provider_json->'services')
            LOOP
                INSERT INTO public.services (venue_id, name, description, duration, price)
                VALUES (
                    new_venue_id,
                    service_json->>'name',
                    service_json->>'desc',
                    (service_json->>'duration')::int,
                    (service_json->>'price')::numeric
                );
            END LOOP;

            -- Insert availability for this venue (Monday-Saturday, 9am-6pm)
            -- day_of_week: 0=Sunday, 1=Monday, 2=Tuesday, 3=Wednesday, 4=Thursday, 5=Friday, 6=Saturday
            FOR day_num IN 1..6 LOOP
                INSERT INTO public.availability (venue_id, day_of_week, start_time, end_time)
                VALUES (
                    new_venue_id,
                    day_num,
                    '09:00:00'::TIME,
                    '18:00:00'::TIME
                );
            END LOOP;

            -- Add Sunday availability for some venues (Food category stays open)
            IF (provider_json->>'category') = 'Food' THEN
                INSERT INTO public.availability (venue_id, day_of_week, start_time, end_time)
                VALUES (
                    new_venue_id,
                    0, -- Sunday
                    '10:00:00'::TIME,
                    '20:00:00'::TIME
                );
            END IF;

        END LOOP;
    END LOOP;

    -- Set all providers as venue_owner role
    UPDATE public.users SET role = 'venue_owner';

END $$;
